//! 🧪️ Actual original evaluation receiving preserves typed Dictionary source/cache custody against independent Serde.
use super::*;
use semio_framework_os_flow_host_session::evaluation_receiving::*;
use semio_framework_value::RetirementDemand;
use semio_framework_value::retained_clone::RetainedCloneGrant;
use semio_framework_value::{DslValue, Number};
use semio_framework_job::{StepContextOwner,StepBudget,OperationId,Generation,root_cancel_token};
use semio_framework_value::ToValue;
fn observe<T>(action:impl FnOnce()->T)->(T,(usize,usize)){let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(action);(result,(heap.requested_bytes,heap.released_bytes))}
fn dto(value:&serde_json::Value)->DslValue{match value{serde_json::Value::Null=>DslValue::Null,serde_json::Value::Bool(value)=>DslValue::Bool(*value),serde_json::Value::Number(value)=>DslValue::Number(value.as_u64().map(Number::UInt).unwrap_or_else(||Number::Float(value.as_f64().unwrap()))),serde_json::Value::String(value)=>DslValue::String(value.clone()),serde_json::Value::Array(value)=>DslValue::Array(value.iter().map(dto).collect()),serde_json::Value::Object(value)=>DslValue::Object(value.iter().map(|(key,value)|(key.clone(),dto(value))).collect())}}
fn grant(d:RetirementDemand,body:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:body,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn caller()->StepContextOwner{StepContextOwner::new(OperationId(706),Generation(9),RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:StepContextOwner::birth_bytes(),maximum_depth:1,..Default::default()}).unwrap().0}
#[test]
fn original_completed_preview_evaluation_donates_dictionary_to_actual_original_paid_cache(){
 let fixture:serde_json::Value=serde_json::from_str(read_node("📥️evaluation-source/🔎️read/📨️response/🧫️fixtures/🧠️dictionary.json")).unwrap();let address=FlowEvaluationReplyAddress{node_hash:u64::MAX,window_id:"original-preview",window_kind_id:"world3d"};
 for body in[1,3,64]{let((source,mut session),heap)=observe(||(dto(&fixture),FlowEvalSession::new()));let mut sums=heap;let mut issuer=caller();let cancel=root_cancel_token();let mut sequence=0;
  for turn in 0..1000{let d=RetirementDemand{copy_bytes:session.next_window_tick_latch_copy_byte_demand(address.window_id).unwrap(),capacity_bytes:session.next_window_tick_latch_capacity_byte_demand(address.window_id,64).unwrap(),release_bytes:session.next_window_tick_latch_release_byte_demand(address.window_id).unwrap(),depth:session.next_window_tick_latch_depth_demand(address.window_id).unwrap().max(1)};let mut physical=Default::default();let mut cx=issuer.context(StepBudget::new(1,u64::MAX,grant(d,64)),cancel.clone(),||Some(1),&mut sequence,&mut physical).unwrap();let(step,heap)=observe(||semio_framework_job::close_original_retained_step(&mut cx,d,|g|session.prepare_window_tick_latch(address.window_id,g).map_err(|(error,p)|error.with_retained_progress(p))));let p=cx.retained_progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));sums.0+=heap.0;sums.1+=heap.1;step.unwrap();if session.window_tick_latches.contains_key(&flow_eval_window_key(address.window_id)){break}assert!(turn<999)}
  let mut physical=Default::default();let mut cx=issuer.context(StepBudget::new(1,u64::MAX,RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()}),cancel.clone(),||Some(1),&mut sequence,&mut physical).unwrap();let(mut receiver,heap)=observe(||FlowEvaluationReplyReceiver::new(source,&mut cx).unwrap_or_else(|_|panic!("original Dictionary reply intake")));assert_eq!(heap,(0,0));drop(cx);
  for turn in 0..200000{if receiver.terminal_is_empty(){break}assert!(turn<199999);let d=receiver.next_demands(&session,body,address.window_id).unwrap();let g=grant(d,body);let before=(receiver.scan,receiver.phase,receiver.field,receiver.slots);
   for denied in[Some(RetainedCloneGrant{maximum_items:0,..g}),Some(RetainedCloneGrant{maximum_depth:0,..g}),(d.copy_bytes>body).then_some(g),(d.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.release_bytes>0).then_some(RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g})].into_iter().flatten(){let mut physical=Default::default();let mut cx=issuer.context(StepBudget::new(1,u64::MAX,denied),cancel.clone(),||Some(1),&mut sequence,&mut physical).unwrap();let(result,heap)=observe(||receiver.step(&mut session,&address,&mut cx));assert!(!result.unwrap());assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),Default::default());assert_eq!(cx.fuel_remaining(),1);assert_eq!((receiver.scan,receiver.phase,receiver.field,receiver.slots),before);}
   let mut physical=Default::default();let mut cx=issuer.context(StepBudget::new(1,u64::MAX,g),cancel.clone(),||Some(1),&mut sequence,&mut physical).unwrap();let(result,heap)=observe(||receiver.step(&mut session,&address,&mut cx));let p=cx.retained_progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert!(p.fits(g));sums.0+=heap.0;sums.1+=heap.1;result.unwrap();if d.copy_bytes>body{assert_eq!(p,Default::default());break}
  }
  if body==64{assert!(receiver.terminal_is_empty()&&receiver.received);let cache=session.neural_cache.as_ref().unwrap();assert_eq!(cache.len(),1);let actual=cache.inspect_original(u64::MAX,ToValue::to_value).unwrap();assert_eq!(actual,dto(&fixture["output"]));}else{assert!(session.neural_cache.as_ref().unwrap().is_empty());}
  cancel.cancel_now();receiver.begin_close();for turn in 0..200000{if receiver.terminal_is_empty(){break}assert!(turn<199999);let d=receiver.next_close_demands(3).unwrap();let mut physical=Default::default();let mut cx=issuer.context(StepBudget::new(1,u64::MAX,grant(d,3)),cancel.clone(),||Some(1),&mut sequence,&mut physical).unwrap();let(step,heap)=observe(||receiver.close_step(&mut cx));let p=cx.retained_progress();assert_eq!(step.unwrap().progress(),p);assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));sums.0+=heap.0;sums.1+=heap.1;}
  session.begin_close();for turn in 0..200000{if session.terminal_is_empty(){break}assert!(turn<199999);let d=RetirementDemand{copy_bytes:session.next_close_copy_byte_demand().unwrap(),capacity_bytes:session.next_close_capacity_byte_demand(3).unwrap(),release_bytes:session.next_close_release_byte_demand().unwrap(),depth:session.next_close_depth_demand().unwrap()};let mut physical=Default::default();let mut cx=issuer.context(StepBudget::new(1,u64::MAX,grant(d,3)),cancel.clone(),||Some(1),&mut sequence,&mut physical).unwrap();let(step,heap)=observe(||semio_framework_job::close_original_retained_step(&mut cx,d,|g|session.close_step(g)));let p=cx.retained_progress();assert_eq!(step.unwrap().progress(),p);assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));sums.0+=heap.0;sums.1+=heap.1;}
  assert_eq!(sums.0,sums.1);assert_eq!(observe(||drop(receiver)).1,(0,0));assert_eq!(observe(||drop(session)).1,(0,0));issuer.close_step(RetainedCloneGrant{maximum_items:1,maximum_release_bytes:StepContextOwner::birth_bytes(),maximum_depth:1,..Default::default()});assert!(issuer.terminal_is_empty());eprintln!("[DEBUG] Original evaluation reply DictionarySerde=true typedCache=true UInt64Max=true body{body} everySystemReceipt=true fullClose=true conservation=true Drop0");
 }
}
